using System.ComponentModel;
using System.Net;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides web search capability to the research agent.
/// In production, replace the simulated results with a real search API (e.g., Bing Search).
/// </summary>
public static class WebSearchTool
{
    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static string SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated search results for demonstration purposes.
        // Replace with a real search API integration (Bing Search, Google Custom Search, etc.)
        var results = new[]
        {
            new { Title = $"Overview of {query}", Snippet = $"A comprehensive overview covering the key aspects of {query}, including history, current state, and future outlook." },
            new { Title = $"Latest developments in {query}", Snippet = $"Recent research and developments related to {query} show significant progress in multiple areas." },
            new { Title = $"{query} - Expert Analysis", Snippet = $"Industry experts provide analysis on {query}, highlighting opportunities and challenges ahead." },
        };

        var formatted = results.Select((r, i) =>
            $"[{i + 1}] {r.Title}\n    {r.Snippet}");

        return $"Search results for \"{query}\":\n\n{string.Join("\n\n", formatted)}";
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking capability so the agent can record findings during research.
/// </summary>
public static class NoteTakingTool
{
    private static readonly List<string> s_notes = [];

    [Description("Saves a research note. Use this to record important findings during research.")]
    public static string SaveNote(
        [Description("The note content to save")] string note)
    {
        s_notes.Add(note);
        return $"Note saved (total notes: {s_notes.Count}).";
    }

    [Description("Retrieves all saved research notes.")]
    public static string GetNotes()
    {
        if (s_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var formatted = s_notes.Select((n, i) => $"[{i + 1}] {n}");
        return $"Saved notes:\n\n{string.Join("\n\n", formatted)}";
    }

    public static void Clear() => s_notes.Clear();
}

