using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Agents.AI;
using ResearchAgent.Tools;

var services = new ServiceCollection();

services.AddLogging(builder => builder
    .AddConsole()
    .SetMinimumLevel(LogLevel.Warning));

// Register the chat client with function invocation support.
// Uses OpenAI — set OPENAI_API_KEY environment variable.
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

const string modelId = "gpt-4o-mini-2024-07-18";

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, apiKey));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();

// Define tools available to the agent
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWeb),
    AIFunctionFactory.Create(NoteTakingTool.SaveNote),
    AIFunctionFactory.Create(NoteTakingTool.GetNotes),
};

// Create the research agent using Microsoft Agent Framework
var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes, then summarizes findings.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [.. tools],
        },
    },
    sp.GetRequiredService<ILoggerFactory>());

// System instruction for the agent
var systemMessage = new ChatMessage(ChatRole.System, """
    You are a research assistant. When given a topic:
    1. Use the SearchWeb tool to find information (make 2-3 searches with different angles).
    2. Use the SaveNote tool to record key findings from each search.
    3. Use the GetNotes tool to review all your findings.
    4. Provide a comprehensive summary of your research.

    Be thorough but concise. Focus on factual information.
    """);

// Get the research topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('-', 60));

// Run the agent
var session = await agent.CreateSessionAsync();

var messages = new List<ChatMessage>
{
    systemMessage,
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var response = await agent.RunAsync(messages, session, new AgentRunOptions());

Console.WriteLine("\n" + new string('=', 60));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('=', 60));
Console.WriteLine(response.Text);
Console.WriteLine(new string('=', 60));

